func (s *Service) validateBeaconBlockPubSub(ctx context.Context, pid peer.ID, msg *pubsub.Message) (pubsub.ValidationResult, error) {
    receivedTime := prysmTime.Now()
    if pid == s.cfg.p2p.PeerID() {
        return pubsub.ValidationAccept, nil
    }
    if s.cfg.initialSync.Syncing() {
        return pubsub.ValidationIgnore, nil
    }
    ctx, span := trace.StartSpan(ctx, "sync.validateBeaconBlockPubSub")
    defer span.End()
    m, err := s.decodePubsubMessage(msg)
    if err != nil {
        return pubsub.ValidationReject, errors.Wrap(err, "Could not decode message")
    }
    s.validateBlockLock.Lock()
    defer s.validateBlockLock.Unlock()
    blk, ok := m.(interfaces.ReadOnlySignedBeaconBlock)
    if !ok {
        return pubsub.ValidationReject, errors.New("msg is not ethpb.ReadOnlySignedBeaconBlock")
    }
    if blk.IsNil() || blk.Block().IsNil() {
        return pubsub.ValidationReject, errors.New("block.Block is nil")
    }
    // Broadcast block event (even before full validation)
    s.cfg.operationNotifier.OperationFeed().Send(...)
    s.cfg.blockNotifier.BlockFeed().Send(...)
    // Slasher feed (goroutine)
    if s.slasherEnabled {
        go func() { s.cfg.slasherBlockHeadersFeed.Send(blockHeader) }()
    }
    // validateDenebBeaconBlock: checks KZG commitment count only
    if err := validateDenebBeaconBlock(blk.Block()); err != nil {
        return pubsub.ValidationReject, err
    }
    // Proposer dedup check
    if s.hasSeenBlockIndexSlot(blk.Block().Slot(), blk.Block().ProposerIndex()) {
        ... equivocation detection ...
        return pubsub.ValidationIgnore, nil
    }
    blockRoot, err := blk.Block().HashTreeRoot()
    if s.cfg.beaconDB.HasBlock(ctx, blockRoot) { return pubsub.ValidationIgnore, nil }
    if s.hasBadBlock(blk.Block().ParentRoot()) { ... return pubsub.ValidationReject, err }
    // Slot time checks
    if err := slots.VerifyTime(...); err != nil { return pubsub.ValidationIgnore, nil }
    if startSlot >= blk.Block().Slot() { return pubsub.ValidationIgnore, err }
    // Queue early blocks
    if isBlockQueueable(...) { 
        verifyPendingBlockSignature + insertBlockToPendingQueue 
        return pubsub.ValidationIgnore, err 
    }
    // Handle unknown parent
    if !s.cfg.chain.HasBlock(ctx, blk.Block().ParentRoot()) {
        verifyPendingBlockSignature + insertBlockToPendingQueue
        return pubsub.ValidationIgnore, err
    }
    // Full validation
    err = s.validateBeaconBlock(ctx, blk, blockRoot)
    // note: ErrOptimisticParent allows through even with error
    ...
    return pubsub.ValidationAccept, nil
}

func validateDenebBeaconBlock(blk interfaces.ReadOnlyBeaconBlock) error {
    if blk.Version() < version.Deneb { return nil }
    commits, err := blk.Body().BlobKzgCommitments()
    maxBlobsPerBlock := params.BeaconConfig().MaxBlobsPerBlock(blk.Slot())
    if len(commits) > maxBlobsPerBlock {
        return errors.Wrapf(errRejectCommitmentLen, ...)
    }
    return nil
}

func (s *Service) validateBellatrixBeaconBlock(ctx context.Context, parentState state.BeaconState, blk interfaces.ReadOnlyBeaconBlock) error {
    // Checks only: execution enabled, timestamp, optimistic parent
    // Does NOT check: base_fee, gas_limit, extra_data - those are EL responsibilities
    if payload.Timestamp() != uint64(t.Unix()) { return errors.New("incorrect timestamp") }
    if isParentOptimistic { return ErrOptimisticParent }
    return nil
}
